def merge_pair(tokens,a,b):
    out=[]; i=0
    while i<len(tokens):
        if i<len(tokens)-1 and tokens[i]==a and tokens[i+1]==b:
            out.append(a+b); i+=2
        else:
            out.append(tokens[i]); i+=1
    return out

